/** Who may decide for this patient today, by the hospital's consent policy (MSDS 75): the rule the decision is checked with, so a frontend never classifies the patient or hardcodes the age of consent (backend issue #39). */
export interface WhoDecidesOut {
  /** The age of consent in years (setting consent_adult_age) */
  adult_age: number;
  /** patient_age is known and below adult_age. An unknown age counts as an adult, as the database's check does */
  patient_is_minor: boolean;
  /** false for a minor: a decision maker signs (signer DecisionMaker); signer Patient answers CONSENT_SIGNER_INVALID */
  patient_may_sign: boolean;
  /** The relationships allowed to decide for this patient, in the order to ask; any other signer_relationship answers CONSENT_SIGNER_INVALID */
  decision_makers: DecisionMakerChoiceOut[];
  /** mode EmergencyNote needs second_doctor_id: a doctor registered with the PMDC other than the caller (setting consent_emergency_second_doctor; GET /staff/lookup?license_type=PMDC) */
  emergency_second_doctor: boolean;
}

export interface DecisionMakerChoiceOut {
  relationship: "Guardian" | "Attorney" | "Spouse" | "Child" | "Parent" | "Sibling" | "OtherRelative" | "CareProvider";
  description: string;
  /** The order to ask for this patient, the lowest first */
  priority: number;
}

export interface ConsentUpdateIn {
  procedure_name?: string | null;
  /** The employee who performs it (fills performer_name) */
  performer_id?: number | null;
  performer_name?: string | null;
  risks?: string | null;
  benefits?: string | null;
  alternatives?: string | null;
  /** General consent: why the patient is admitted */
  admission_need?: string | null;
  /** General consent: the estimated stay */
  estimated_days?: number | null;
  /** General consent: the estimated cost (PKR) */
  estimated_cost?: number | string | null;
  /** Changing it prints the form's text in the new language */
  language?: "English" | "Urdu" | "Punjabi" | "Saraiki" | "Pashto" | "Sindhi" | "Balochi" | null;
  expected_version?: number | null;
}

export interface PrintOut_ConsentPrintFieldsOut_ {
  document_type: "autopsy_order" | "bed_labels" | "blood_component_label" | "blood_donation_labels" | "clinical_note" | "complaint_letter" | "complaints_notice" | "consent_form" | "cost_estimate" | "cssd_labels" | "death_certificate" | "discharge_summary" | "dispensing_label" | "dose_label" | "id_card" | "imaging_report" | "lab_label" | "lab_report" | "mlc_intimation" | "opd_slip" | "pharmacy_receipt" | "prescription" | "referral_slip" | "send_out_manifest" | "surgical_record" | "triage_algorithm" | "wristband";
  /** Which printer of the terminal to use (GET /api/v1/terminals/whoami) */
  printer_role: "receipt" | "label" | "document" | "card";
  paper_width_mm: number;
  /** The document's data, for frontends that render their own layout */
  fields: ConsentPrintFieldsOut;
  /** Pre-formatted monospace text (48 columns) for ESC/POS printers, as is */
  text: string | null;
  barcode_svg: string | null;
  qr_svg: string | null;
  pdf_url: string | null;
}

export interface ConsentPrintFieldsOut {
  hospital: HospitalHeaderOut;
  consent: ConsentOut;
  /** What the professional explained (blank lines where empty) */
  explained: ConsentLineOut[];
  /** The recorded decision; empty for a draft */
  decision: ConsentLineOut[];
  /** A draft: the lines to sign on paper */
  signature_lines: string[];
}

export interface HospitalHeaderOut {
  name: string;
  address: string;
  phone: string;
  /** The Punjab Healthcare Commission registration / licence number (GET /msds/profile); empty until an admin confirms it */
  phc_number: string;
  /** An issued document: 'Issued <when>; this copy printed <when>', with '(reprint)' an hour or more later; print it under the PHC number. Empty for a report of now */
  issue_line: string;
}

export interface ConsentLineOut {
  label: string;
  value: string;
}

export interface ConsentSignIn {
  /** Patient, or DecisionMaker when the patient cannot decide */
  signer?: "Patient" | "DecisionMaker" | null;
  /** Default for the patient: their name */
  signer_name?: string | null;
  /** A decision maker: one the policy allows for this patient (GET /consent-decision-makers) */
  signer_relationship?: "Guardian" | "Attorney" | "Spouse" | "Child" | "Parent" | "Sibling" | "OtherRelative" | "CareProvider" | null;
  signer_cnic?: string | null;
  signer_phone?: string | null;
  /** Why the patient cannot decide (a decision maker or the emergency note) */
  incapacity_reason?: "Minor" | "Unconscious" | "Confused" | "MentalIllness" | "Sedated" | "Other" | null;
  /** Required for a thumb impression, a verbal refusal and the forms that say so */
  witness_name?: string | null;
  witness_role?: string | null;
  interpreter_name?: string | null;
  /** The text was read aloud (the patient cannot read it) */
  read_to_patient?: boolean;
  /** The questions asked and the answers given; "None asked" (required when signed) */
  questions_answers?: string | null;
  /** The patient (or decision maker) explained it back in their own words (required when signed) */
  understanding_confirmed?: boolean;
  /** When it was signed; default now, never in the future */
  decided_at?: string | null;
  expected_version?: number | null;
  /** EmergencyNote: nobody could consent and the treatment could not wait (a doctor writes it) */
  mode?: "Signed" | "EmergencyNote";
  signer_mark?: "Signature" | "ThumbImpression";
  /** Why the treatment could not wait and nobody could consent */
  emergency_note?: string | null;
  /** The second registered doctor who concurs with the emergency note (setting consent_emergency_second_doctor): an employee_id from GET /staff/lookup?license_type=PMDC */
  second_doctor_id?: number | null;
}

export interface ConsentRefuseIn {
  /** Patient, or DecisionMaker when the patient cannot decide */
  signer?: "Patient" | "DecisionMaker" | null;
  /** Default for the patient: their name */
  signer_name?: string | null;
  /** A decision maker: one the policy allows for this patient (GET /consent-decision-makers) */
  signer_relationship?: "Guardian" | "Attorney" | "Spouse" | "Child" | "Parent" | "Sibling" | "OtherRelative" | "CareProvider" | null;
  signer_cnic?: string | null;
  signer_phone?: string | null;
  /** Why the patient cannot decide (a decision maker or the emergency note) */
  incapacity_reason?: "Minor" | "Unconscious" | "Confused" | "MentalIllness" | "Sedated" | "Other" | null;
  /** Required for a thumb impression, a verbal refusal and the forms that say so */
  witness_name?: string | null;
  witness_role?: string | null;
  interpreter_name?: string | null;
  /** The text was read aloud (the patient cannot read it) */
  read_to_patient?: boolean;
  /** The questions asked and the answers given; "None asked" (required when signed) */
  questions_answers?: string | null;
  /** The patient (or decision maker) explained it back in their own words (required when signed) */
  understanding_confirmed?: boolean;
  /** When it was signed; default now, never in the future */
  decided_at?: string | null;
  expected_version?: number | null;
  /** VerbalRefusal: refused and would not sign (a witness is required) */
  mode?: "Signed" | "VerbalRefusal";
  signer_mark?: "Signature" | "ThumbImpression";
  /** The reason, in the patient's words */
  refusal_reason: string;
}

export interface ConsentReasonIn {
  reason: string;
}

export interface ConsentScanIn {
  /** A patient document of type Consent: POST /patients/{patient_id}/documents */
  document_id: number;
}

/** The stored document (download it with GET /patient-documents/{document_id}/download). */
export interface PatientDocumentUploadOut {
  document_id: number;
  patient_id: number;
  doc_type: "Photo" | "CNIC" | "PanelCard" | "Consent" | "ReferralLetter" | "DeathCertificate" | "AutopsyReport" | "PostMortemReport" | "MedicoLegalReport" | "LabReport" | "Imaging" | "DischargeSummary" | "Prescription" | "Other";
  title: string | null;
  content_type: "application/pdf" | "image/jpeg" | "image/png";
  size_bytes: number;
  /** Brought by the patient from another hospital, laboratory or clinic: show it labelled as an outside document, never as a result of this hospital */
  is_outside: boolean;
  /** The hospital, laboratory or clinic that issued an outside document */
  source_facility: string | null;
  /** The date written on the document (the test, the report, the visit) */
  document_date: string | null;
  uploaded_at: string;
}

/** Operations whose surgical record needs work — GET /api/v1/ot/clinical-worklist (who may call: holders of ot.clinical.view). */
export function worklistOtClinical(query?: { mine?: boolean; days?: number; admission_id?: number | null }): Promise<SurgicalWorklistItemOut[]> {
  return api<SurgicalWorklistItemOut[]>("GET", withQuery(`/ot/clinical-worklist`, query), undefined);
}

